public final class ScannerAndroidTests {
 static int checks;static void ok(boolean v,String label){if(!v)throw new AssertionError(label);checks++;System.out.println("OK "+label);}
 public static void main(String[] args)throws Exception {System.setOut(new PrintStream(new FileOutputStream(FileDescriptor.out),true,"UTF-8"));try{run(args);}catch(Throwable e){e.printStackTrace(System.out);System.exit(1);}}
 static byte[] bytes(File f)throws Exception{return Files.readAllBytes(f.toPath());}
 static void run(String[] args)throws Exception {
  File root=new File(args[0]);if(Looper.myLooper()==null)Looper.prepareMainLooper();Class<?> activityThread=Class.forName("android.app.ActivityThread");Object thread=activityThread.getMethod("systemMain").invoke(null);Context system=(Context)activityThread.getMethod("getSystemContext").invoke(thread);
  AssetManager assets=AssetManager.class.getDeclaredConstructor().newInstance();AssetManager.class.getMethod("addAssetPath",String.class).invoke(assets,new File(root,"assets.apk").getAbsolutePath());File data=new File(root,"data"),files=new File(root,"files");data.mkdirs();files.mkdirs();Context c=new ContextWrapper(system){public Context getApplicationContext(){return this;}public File getNoBackupFilesDir(){return data;}public File getFilesDir(){return files;}public AssetManager getAssets(){return assets;}public String getPackageName(){return "dev.pocketllama.scanner.qa";}};
  DocumentEdges.load();Bitmap board=Bitmap.createBitmap(1000,1400,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(board);canvas.drawColor(0xff303735);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setColor(Color.WHITE);android.graphics.Path doc=new android.graphics.Path();float[] points={130,160,890,220,820,1250,70,1170};doc.moveTo(points[0],points[1]);for(int i=1;i<4;i++)doc.lineTo(points[i*2],points[i*2+1]);doc.close();canvas.drawPath(doc,paint);paint.setColor(Color.RED);canvas.drawCircle(185,235,35,paint);paint.setColor(Color.GREEN);canvas.drawCircle(820,290,35,paint);paint.setColor(Color.BLUE);canvas.drawCircle(760,1165,35,paint);paint.setColor(Color.YELLOW);canvas.drawCircle(140,1090,35,paint);
  double[] edges=DocumentEdges.detect(board);ok(edges!=null,"OpenCV document contour");double[] expected={.13,160./1400,.89,220./1400,.82,1250./1400,.07,1170./1400};ok(ScanGeometry.distance(edges,expected)<.025,"document corners within 2.5% of fixture");
  PhotoStore photos=new PhotoStore(c);String id=PhotoImages.save(c,ScanImages.jpeg(board,95));byte[] original=photos.image(id,false);photos.scan(id,ScanGeometry.json(edges),"color");Bitmap rectified=ScanImages.render(original,photos.get(id),4096);try(OutputStream out=new FileOutputStream(new File(root,"rectified.png"))){rectified.compress(Bitmap.CompressFormat.PNG,100,out);}int[] size=ScanGeometry.size(edges,1000,1400);ok(rectified.getWidth()==size[0]&&rectified.getHeight()==size[1],"perspective output dimensions");ok(Color.red(rectified.getPixel(rectified.getWidth()/2,rectified.getHeight()/2))>220,"paper perspective crop removes dark exterior");rectified.recycle();
  photos.scan(id,ScanGeometry.json(edges),"bw");Bitmap bw=ScanImages.render(original,photos.get(id),1600);int[] px=new int[bw.getWidth()*bw.getHeight()];bw.getPixels(px,0,bw.getWidth(),0,0,bw.getWidth(),bw.getHeight());int nonbinary=0;for(int value:px)if((value&0xffffff)!=0&&(value&0xffffff)!=0xffffff)nonbinary++;ok(nonbinary==0,"adaptive black-and-white output is binary");int w=bw.getWidth(),h=bw.getHeight();bw.recycle();photos.rotate(id);Bitmap rotated=ScanImages.render(original,photos.get(id),1600);ok(rotated.getWidth()==h&&rotated.getHeight()==w,"quarter-turn after crop/filter");rotated.recycle();ok(Arrays.equals(original,photos.image(id,false)),"encrypted original unchanged by transformations");board.recycle();
  if(args.length>1&&args[1].equals("post")){java.lang.reflect.Method method=SuryaDetector.class.getDeclaredMethod("boxes",float[].class,int.class,int.class,int.class,int.class,int.class,int.class,SuryaRuntime.Check.class);method.setAccessible(true);float[] map=new float[90000];java.nio.ByteBuffer.wrap(bytes(new File(root,"scan-heatmap.f32"))).order(java.nio.ByteOrder.LITTLE_ENDIAN).asFloatBuffer().get(map);JSONArray lines=(JSONArray)method.invoke(null,map,300,300,1200,1200,0,1200,(SuryaRuntime.Check)()->{});ok(lines.length()==5,"Android OpenCV decodes five lines from actual ORT 1.22 output");JSONArray empty=(JSONArray)method.invoke(null,new float[90000],300,300,1200,1200,0,1200,(SuryaRuntime.Check)()->{});ok(empty.length()==0,"zero heatmap produces no fabricated text boxes");Files.write(new File(root,"detection.json").toPath(),lines.toString(2).getBytes("UTF-8"));}
  else {
  File detector=SuryaAssets.detector(c);ok(detector.length()==153847992,"detector copied and SHA verified on Android");Bitmap fixture=BitmapFactory.decodeFile(new File(root,"scan-page.jpg").getAbsolutePath());long started=SystemClock.elapsedRealtime();try(SuryaDetector model=new SuryaDetector(detector)){JSONArray lines=model.detect(fixture,()->{});ok(lines.length()==5,"Android ONNX Runtime 1.22 + OpenCV detects five fixture lines");Files.write(new File(root,"detection.json").toPath(),lines.toString(2).getBytes("UTF-8"));Bitmap blank=Bitmap.createBitmap(500,700,Bitmap.Config.ARGB_8888);blank.eraseColor(Color.WHITE);ok(model.detect(blank,()->{}).length()==0,"blank page has no fabricated text boxes");blank.recycle();}System.out.println("Detector ms "+(SystemClock.elapsedRealtime()-started));fixture.recycle();
  }
  JSONObject html=SafeOcrHtml.parse("<p onclick=steal()>Тест</p><script>bad()</script><table><tr><td rowspan=2>500 ₽</td><td>Итого</td></tr><tr><td>600 ₽</td></tr></table>");ok(html.getJSONArray("tables").length()==1&&!html.getString("html").contains("onclick")&&!html.getString("html").contains("bad()"),"jsoup sanitization and rowspan on Android ART");
  DocumentStore docs=new DocumentStore(c);String document=docs.resolve(id);ok(docs.detail(document).getJSONArray("pages").length()==1,"production encrypted document index on Android");docs.add(document,PhotoImages.save(c,original));ok(docs.detail(document).getJSONArray("pages").length()==2,"multipage index persists on Android");
  photos.edit(id,"Счёт № 7 — проверка PDF");File pdf=new File(root,"export.pdf");try(OutputStream out=new FileOutputStream(pdf)){ScanExports.write(c,document,"pdf",out);}try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(pdf,ParcelFileDescriptor.MODE_READ_ONLY);android.graphics.pdf.PdfRenderer renderer=new android.graphics.pdf.PdfRenderer(fd)){ok(renderer.getPageCount()==2,"exported PDF opens in Android PDFium");try(android.graphics.pdf.PdfRenderer.Page first=renderer.openPage(0)){Bitmap bitmap=Bitmap.createBitmap(595,842,Bitmap.Config.ARGB_8888);first.render(bitmap,null,null,android.graphics.pdf.PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);bitmap.recycle();ok(true,"PDF image and embedded font render on Android");}}
  System.out.println("PASS: "+checks+" Android scanner checks");
 }
}
